 static async Task RequireActive(HttpClient c,string logical,Guid id,CancellationToken ct,string message){var m=await DataverseMetadataResolver.TableAsync(c,logical,ct);if(await DataverseMetadataResolver.ReadOneAsync(c,$"{m.EntitySetName}({id:D})?$select={m.PrimaryIdAttribute},statecode",ct) is not{} x||(Int(x,"statecode")??0)!=0)throw new ArgumentException(message);}
