 static async Task<JsonElement> One(HttpClient c,string path,CancellationToken ct)=>await DataverseMetadataResolver.ReadOneAsync(c,path,ct)??throw new KeyNotFoundException("El registro no existe.");
 static async Task Ensure(HttpResponseMessage r,CancellationToken ct){if(r.IsSuccessStatusCode)return;var content=await r.Content.ReadAsStringAsync(ct);throw new InvalidOperationException($"Dataverse rechazó la operación ({(int)r.StatusCode}): {ErrorMessage(content)}");}
 static string ErrorMessage(string content){try{using var document=JsonDocument.Parse(content);return document.RootElement.GetProperty("error").GetProperty("message").GetString()??"Error sin descripción.";}catch(JsonException){return"Respuesta no válida de Dataverse.";}}
 static Guid CreatedId(HttpResponseMessage r){var uri=r.Headers.TryGetValues("OData-EntityId",out var values)?values.SingleOrDefault():null;var match=System.Text.RegularExpressions.Regex.Match(uri??"",@"\(([0-9a-f-]{36})\)$");return match.Success?Guid.Parse(match.Groups[1].Value):throw new InvalidOperationException("Dataverse no devolvió el identificador creado.");}
 static string Esc(string x)=>x.Replace("'","''",StringComparison.Ordinal);static string? Str(JsonElement x,string p)=>x.TryGetProperty(p,out var v)&&v.ValueKind==JsonValueKind.String?v.GetString():null;static int? Int(JsonElement x,string p)=>DataverseJson.OptionalEncodedInt32(x,p);static bool? Bool(JsonElement x,string p)=>x.TryGetProperty(p,out var v)&&v.ValueKind is JsonValueKind.True or JsonValueKind.False?v.GetBoolean():null;static bool Present(JsonElement x,string p)=>x.TryGetProperty(p,out var v)&&v.ValueKind is not(JsonValueKind.Null or JsonValueKind.Undefined)&&(!(v.ValueKind==JsonValueKind.String)||!string.IsNullOrWhiteSpace(v.GetString()));static DateTimeOffset? Date(JsonElement x,string p)=>DateTimeOffset.TryParse(Str(x,p),CultureInfo.InvariantCulture,DateTimeStyles.AssumeUniversal,out var d)?d:null;static Guid GuidVal(JsonElement x,string p)=>GuidValNullable(x,p)??Guid.Empty;static Guid? GuidValNullable(JsonElement x,string p)=>Guid.TryParse(Str(x,$"_{p}_value"),out var g)?g:null;static string? Formatted(JsonElement x,string p)=>Str(x,$"_{p}_value@OData.Community.Display.V1.FormattedValue");
 sealed record TypeFields(string Id,string Name,string Code,string Color,string Description,string Order){public string Select=>string.Join(',',Id,Name,Code,Color,Description,Order,"statecode");public static TypeFields From(DataverseTableMetadata m)=>new(m.PrimaryIdAttribute,m.Attribute("gaia_Nombre"),m.Attribute("gaia_Codigo"),m.Attribute("gaia_Color"),m.Attribute("gaia_Descripcion"),m.Attribute("gaia_Orden"));}
 sealed record EventFields(string Id,string Name,string TypeLookup,string TypeNav,string Summary,string Description,string Start,string End,string AllDay,string Modality,string Location,string Url,string Status,string RequesterLookup,string RequesterNav){public string Select=>string.Join(',',Id,Name,$"_{TypeLookup}_value",Summary,Description,Start,End,AllDay,Modality,Location,Url,Status,$"_{RequesterLookup}_value","statecode");public static EventFields From(DataverseTableMetadata m){var t=m.Relationship("gaia_TipoEvento",Types);var r=m.Relationship("gaia_Solicitante","gaia_terceros");return new(m.PrimaryIdAttribute,m.Attribute("gaia_Nombre"),t.ReferencingAttribute,t.NavigationProperty,m.Attribute("gaia_Resumen"),m.Attribute("gaia_Descripcion"),m.Attribute("gaia_FechaInicio"),m.Attribute("gaia_FechaFin"),m.Attribute("gaia_TodoDia"),m.Attribute("gaia_Modalidad"),m.Attribute("gaia_Ubicacion"),m.Attribute("gaia_EnlaceEvento"),m.Attribute("gaia_Estado"),r.ReferencingAttribute,r.NavigationProperty);}}
